ALTER SEQUENCE public.activity_entity_id_seq OWNED BY public.activity_entity.id;


--
-- Name: document_entity; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.document_entity (
    id integer NOT NULL,
    "programmeId" character varying NOT NULL,
    "verificationRequestId" integer,
    "activityId" integer,
    "userId" integer NOT NULL,
    "companyId" integer NOT NULL,
    version integer NOT NULL,
    status public.document_entity_status_enum DEFAULT 'PENDING'::public.document_entity_status_enum NOT NULL,
    "lastActionByUserId" integer,
    type public.document_entity_type_enum NOT NULL,
    content jsonb,
    "createdTime" bigint NOT NULL,
    "updatedTime" bigint NOT NULL
);


--
-- Name: activity_view_entity; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.activity_view_entity AS
 SELECT a."refId",
    a."projectRefId",
    a.state AS stage,
    a."updatedTime" AS "activityLastUpdatedDate",
    jsonb_object_agg(d.type, jsonb_build_object('createdDate', d."createdTime", 'documentType', d.type, 'refId', d.id, 'version', d.version)) FILTER (WHERE (d.id IS NOT NULL)) AS documents
   FROM (public.activity_entity a
     LEFT JOIN LATERAL ( SELECT DISTINCT ON (d1.type) d1.id,
            d1."programmeId",
            d1."verificationRequestId",
            d1."activityId",
            d1."userId",
            d1."companyId",
            d1.version,
            d1.status,
            d1."lastActionByUserId",
            d1.type,
            d1.content,
            d1."createdTime",
            d1."updatedTime"
           FROM public.document_entity d1
          WHERE ((d1."activityId" = a.id) AND (d1.type = ANY (ARRAY['MONITORING'::public.document_entity_type_enum, 'VERIFICATION'::public.document_entity_type_enum])))
          ORDER BY d1.type, d1.version DESC) d ON (true))
  GROUP BY a."refId", a."projectRefId", a."updatedTime", a.state;


