--
-- Name: credit_block_balances_view_entity; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.credit_block_balances_view_entity AS
 SELECT cb."creditBlockId" AS id,
    cb."serialNumber",
    (cb."creditAmount" - cb."reservedCreditAmount") AS "creditAmount",
    cb."createTime" AS "createdDate",
    cb."projectRefId" AS "projectId",
    p.title AS "projectName",
    cb."ownerCompanyId" AS "receiverId",
    r.name AS "receiverName",
    r.logo AS "receiverLogo",
    cb."previousOwnerCompanyId" AS "senderId",
    s.name AS "senderName",
    s.logo AS "senderLogo",
        CASE
            WHEN (cb."isNotTransferred" = true) THEN 'issued'::text
            ELSE 'received'::text
        END AS type
   FROM (((public.credit_blocks_entity cb
     LEFT JOIN public.project_entity p ON ((cb."projectRefId" = (p."refId")::text)))
     LEFT JOIN public.company r ON ((cb."ownerCompanyId" = r."companyId")))
     LEFT JOIN public.company s ON ((cb."previousOwnerCompanyId" = s."companyId")))
  WHERE (cb."ownerCompanyId" <> 0);


