    "recieverId" bigint NOT NULL,
    type public.credit_transactions_entity_type_enum NOT NULL,
    status public.credit_transactions_entity_status_enum NOT NULL,
    "creditBlockId" text NOT NULL,
    "serialNumber" text NOT NULL,
    amount integer NOT NULL,
    "projectRefId" text NOT NULL,
    "retirementType" public.credit_transactions_entity_retirementtype_enum,
    remarks text,
    country text,
    "organizationName" text,
    "createTime" bigint NOT NULL
);


--
-- Name: credit_block_retirements_view_entity; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.credit_block_retirements_view_entity AS
 SELECT ct.id,
    ct."serialNumber",
    ct.amount AS "creditAmount",
    ct."createTime" AS "createdDate",
    ct."retirementType",
    ct.status,
    ct."projectRefId" AS "projectId",
    country.name AS country,
    ct."organizationName",
    ct.remarks,
    p.title AS "projectName",
    ct."senderId",
    s.name AS "senderName",
    s.logo AS "senderLogo"
   FROM (((public.credit_transactions_entity ct
     LEFT JOIN public.project_entity p ON ((ct."projectRefId" = (p."refId")::text)))
     LEFT JOIN public.company s ON ((ct."senderId" = s."companyId")))
     LEFT JOIN public.country ON ((ct.country = (country.alpha2)::text)))
  WHERE (ct.type = 'Retired'::public.credit_transactions_entity_type_enum);


--
-- Name: credit_block_transfers_view_entity; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.credit_block_transfers_view_entity AS
 SELECT ct.id,
    ct."serialNumber",
    ct.amount AS "creditAmount",
    ct."createTime" AS "createdDate",
    ct."projectRefId" AS "projectId",
    p.title AS "projectName",
    ct."recieverId",
    r.name AS "receiverName",
    r.logo AS "receiverLogo",
    ct."senderId",
    s.name AS "senderName",
    s.logo AS "senderLogo"
   FROM (((public.credit_transactions_entity ct
     LEFT JOIN public.project_entity p ON ((ct."projectRefId" = (p."refId")::text)))
     LEFT JOIN public.company r ON ((ct."recieverId" = r."companyId")))
     LEFT JOIN public.company s ON ((ct."senderId" = s."companyId")))
  WHERE (ct.type = 'Transfered'::public.credit_transactions_entity_type_enum);


