--

CREATE VIEW public.project_details_view_entity AS
 SELECT p."refId",
    p.title,
    p."serialNumber" AS "serialNo",
    p."authorizationId",
    p."projectProposalStage",
    p."creditEst",
    p."creditBalance",
    p."creditRetired",
    p."creditTransferred",
    p."independentCertifiers" AS "certifierId",
    p."noObjectionLetterUrl",
    jsonb_build_object('name', c.name, 'logo', c.logo, 'companyRole', c."companyRole", 'state', c.state, 'email', c.email, 'companyId', p."companyId") AS company
   FROM (public.project_entity p
     JOIN public.company c ON ((p."companyId" = c."companyId")));


