    p."creditBalance",
    p."creditRetired",
    p.sector,
    p."sectoralScope",
    p."authorizationId",
    p."independentCertifiers",
    c."companyId",
    c.name,
    c.logo,
    c."companyRole"
   FROM (public.project_entity p
     JOIN public.company c ON ((p."companyId" = c."companyId")));


