--
-- Name: credit_audit_log_view_entity _RETURN; Type: RULE; Schema: public; Owner: -
--

CREATE OR REPLACE VIEW public.credit_audit_log_view_entity AS
 SELECT cal.id,
    cal."programmeId",
    cal.type,
    cal.country,
    cal.credits,
    cal."createdTime",
    cal."createdBy",
    prog.title AS "programmeTitle",
    prog.sector AS "programmeSector",
    EXTRACT(epoch FROM cal."createdTime") AS created_epoch,
    prog."companyId" AS "programmeCompanyId",
    json_agg(DISTINCT com.*) AS company
   FROM ((public.credit_audit_log cal
     LEFT JOIN public.programme prog ON (((prog."programmeId")::text = (cal."programmeId")::text)))
     LEFT JOIN public.company com ON ((com."companyId" = ANY (prog."companyId"))))
  GROUP BY cal.id, prog."programmeId"
  ORDER BY cal.id;


--
-- Name: investment_view _RETURN; Type: RULE; Schema: public; Owner: -
--

CREATE OR REPLACE VIEW public.investment_view AS
 SELECT investment."requestId",
    investment."programmeId",
    investment.amount,
    investment.instrument,
    investment."interestRate",
    investment."resultMetric",
    investment."paymentPerMetric",
    investment.comments,
    investment.type,
    investment."guaranteePayback",
    investment."insurancePayback",
    investment.level,
    investment.stream,
    investment."esgClassification",
    investment.status,
    investment."fromCompanyId",
    investment.percentage,
    investment."startOfPayback",
    investment.period,
    investment."shareFromOwner",
    investment."toCompanyId",
    investment.initiator,
    investment."initiatorCompanyId",
    investment."txTime",
    investment."createdTime",
    investment."txRef",
    investment.category,
    investment."investmentName",
    investment."nationalInvestmentId",
    json_agg(DISTINCT requester.*) AS requester,
    json_agg(DISTINCT receiver.*) AS receiver,
    receiver."geographicalLocationCordintes" AS "toGeo",
    prog.title AS "programmeTitle",
    prog.sector AS "programmeSector",
    json_agg(DISTINCT sender.*) AS sender,
    sender."geographicalLocationCordintes" AS "fromGeo",
    prog."proponentTaxVatId",
    prog."proponentPercentage",
    prog."creditOwnerPercentage",
    prog."companyId"
   FROM ((((public.investment investment
     LEFT JOIN public.programme prog ON (((prog."programmeId")::text = (investment."programmeId")::text)))
     LEFT JOIN public.company requester ON ((requester."companyId" = investment."initiatorCompanyId")))
     LEFT JOIN public.company receiver ON ((receiver."companyId" = investment."toCompanyId")))
     LEFT JOIN public.company sender ON ((sender."companyId" = investment."fromCompanyId")))
  GROUP BY investment."requestId", requester."companyId", prog."programmeId", receiver."geographicalLocationCordintes", sender."geographicalLocationCordintes";


--
-- Name: ndc_action_view_entity _RETURN; Type: RULE; Schema: public; Owner: -
--

CREATE OR REPLACE VIEW public.ndc_action_view_entity AS
 SELECT ndc_action.id,
    ndc_action."programmeId",
    ndc_action.action,
    ndc_action.methodology,
    ndc_action."typeOfMitigation",
    ndc_action."subTypeOfMitigation",
    ndc_action."agricultureProperties",
    ndc_action."solarProperties",
    ndc_action."creditCalculationProperties",
    ndc_action."adaptationProperties",
    ndc_action."ndcFinancing",
    ndc_action."coBenefitsProperties",
    ndc_action."enablementProperties",
    ndc_action."txTime",
    ndc_action."createdTime",
    ndc_action."constantVersion",
    ndc_action.sector,
    ndc_action.status,
    programme."companyId",
    programme.title AS "programmeName",
    programme."emissionReductionExpected",
    programme."emissionReductionAchieved",
    json_agg(DISTINCT company.*) AS company
   FROM ((public.ndc_action ndc_action
     LEFT JOIN public.programme programme ON (((programme."programmeId")::text = (ndc_action."programmeId")::text)))
     LEFT JOIN public.company company ON ((company."companyId" = ANY (programme."companyId"))))
  GROUP BY ndc_action.id, programme."companyId", programme.title, programme."emissionReductionExpected", programme."emissionReductionAchieved";


--
-- Name: programme_document_view_entity _RETURN; Type: RULE; Schema: public; Owner: -
