    programme_document.url,
    programme_document.type,
    programme_document."txTime",
    programme_document.status,
    programme_document.remark,
    programme."companyId",
    json_agg(DISTINCT company.*) AS company
   FROM ((public.programme_document programme_document
     LEFT JOIN public.programme programme ON (((programme."programmeId")::text = (programme_document."programmeId")::text)))
     LEFT JOIN public.company company ON ((company."companyId" = ANY (programme."companyId"))))
  GROUP BY programme_document.id, programme."companyId";


--
-- Name: programme_query_entity _RETURN; Type: RULE; Schema: public; Owner: -
--

CREATE OR REPLACE VIEW public.programme_query_entity AS
 SELECT programme."programmeId",
    programme."serialNo",
    programme.title,
    programme."externalId",
    programme."sectoralScope",
    programme.sector,
    programme."countryCodeA2",
    programme."currentStage",
    programme."startTime",
    programme."endTime",
    programme."creditEst",
    programme."emissionReductionExpected",
    programme."emissionReductionAchieved",
    programme."creditChange",
    programme."creditIssued",
    programme."creditBalance",
    programme."creditRetired",
    programme."creditFrozen",
    programme."creditTransferred",
    programme."constantVersion",
    programme."proponentTaxVatId",
    programme."companyId",
    programme.article6trade,
    programme.article68trade,
    programme.article64trade,
    programme.article62trade,
    programme."mvcAdjust",
    programme."mvcUnadjusted",
    programme.implementinguser,
    programme.supportingowners,
    programme."proponentPercentage",
    programme."creditOwnerPercentage",
    programme."certifierId",
    programme."revokedCertifierId",
    programme."creditUnit",
    programme."programmeProperties",
    programme."mitigationActions",
    programme."txTime",
    programme."createdTime",
    programme."authTime",
    programme."creditUpdateTime",
    programme."statusUpdateTime",
    programme."certifiedTime",
    programme."txRef",
    programme."txType",
    programme."geographicalLocationCordintes",
    programme."projectLocation",
    programme."cadtId",
    programme."blockBounds",
    programme."environmentalAssessmentRegistrationNo",
    programme."createdAt",
    programme."updatedAt",
    programme."creditCancelled",
    programme."creditAssigned",
    programme."creditAssignedToExchange",
    json_agg(DISTINCT company.*) AS company,
    json_agg(DISTINCT cert.*) AS certifier
   FROM ((public.programme programme
     LEFT JOIN public.company cert ON ((cert."companyId" = ANY (programme."certifierId"))))
     LEFT JOIN public.company company ON ((company."companyId" = ANY (programme."companyId"))))
  GROUP BY programme."programmeId";


--
-- Name: programme_transfer_view_entity_query _RETURN; Type: RULE; Schema: public; Owner: -
--

CREATE OR REPLACE VIEW public.programme_transfer_view_entity_query AS
 SELECT programme_transfer."requestId",
    programme_transfer."programmeId",
    programme_transfer.initiator,
    programme_transfer."initiatorCompanyId",
    programme_transfer."toCompanyId",
    programme_transfer."toAccount",
    programme_transfer."toCompanyMeta",
    programme_transfer."retirementType",
    programme_transfer."fromCompanyId",
    programme_transfer."creditAmount",
    programme_transfer.comment,
    programme_transfer."txRef",
    programme_transfer."txTime",
    programme_transfer."createdTime",
    programme_transfer."authTime",
    programme_transfer.status,
    programme_transfer."isRetirement",
    programme_transfer."omgePercentage",
    json_agg(DISTINCT requester.*) AS requester,
    json_agg(DISTINCT receiver.*) AS receiver,
    prog."creditBalance",
    prog.title AS "programmeTitle",
    prog."certifierId" AS "programmeCertifierId",
    prog.sector AS "programmeSector",
    prog."sectoralScope" AS "programmeSectoralScope",
    json_agg(DISTINCT certifier.*) AS certifier,
    json_agg(DISTINCT sender.*) AS sender,
    prog."proponentTaxVatId",
    prog."proponentPercentage",
    prog."creditOwnerPercentage",
    prog."companyId",
    prog."serialNo"
   FROM (((((public.programme_transfer programme_transfer
     LEFT JOIN public.programme prog ON (((prog."programmeId")::text = (programme_transfer."programmeId")::text)))
     LEFT JOIN public.company requester ON ((requester."companyId" = programme_transfer."initiatorCompanyId")))
     LEFT JOIN public.company receiver ON ((receiver."companyId" = programme_transfer."toCompanyId")))
     LEFT JOIN public.company sender ON ((sender."companyId" = programme_transfer."fromCompanyId")))
     LEFT JOIN public.company certifier ON ((certifier."companyId" = ANY (prog."certifierId"))))
  GROUP BY programme_transfer."requestId", requester."companyId", prog."programmeId";


